diff --git a/src/core/project.ts b/src/core/project.ts
index 76d1577..524b692 100644
--- a/src/core/project.ts
+++ b/src/core/project.ts
@@ -6,12 +6,40 @@ export interface Record {
   warns: readonly string[];
 }

+const semanticHash = (text: string): string => {
+  const normalized = text
+    .toLowerCase()
+    .replace(/[^a-z0-9\s]/g, " ")
+    .trim()
+    .split(/\s+/)
+    .sort()
+    .join(" ");
+  return normalized;
+};
+
+const deduplicateBySemantics = (entries: readonly string[]): string[] => {
+  const seen = new Map<string, string>();
+  for (const entry of entries) {
+    const hash = semanticHash(entry);
+    if (!seen.has(hash)) {
+      seen.set(hash, entry);
+    }
+  }
+  return Array.from(seen.values());
+};
+
 export const project = (records: readonly Record[]): string => {
   const lines: string[] = [];
   for (const record of records) {
-    for (const entry of record.ruledOut) lines.push(`- ruled out: ${entry}`);
-    for (const limit of record.limits) lines.push(`- limit: ${limit}`);
-    for (const warn of record.warns) lines.push(`- warn: ${warn}`);
+    for (const entry of deduplicateBySemantics(record.ruledOut)) {
+      lines.push(`- ruled out: ${entry}`);
+    }
+    for (const entry of deduplicateBySemantics(record.limits)) {
+      lines.push(`- limit: ${entry}`);
+    }
+    for (const entry of deduplicateBySemantics(record.warns)) {
+      lines.push(`- warn: ${entry}`);
+    }
   }
   return lines.join("\n");
 };
